// It takes the options of [Server] so that what is built here can be told
// where to report its writes and what it may see. Built without them, it
// reports nowhere and sees everything.
func NewAddressPolicyServiceServer(db *ent.Client, opts ...Option) api.AddressPolicyServiceServer {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		opt(&s)
	}
	return AddressPolicyServiceServer{Store: s.Store}
}

// AddressPolicyNarrow answers with `p` and everything else that narrows a
// read of a AddressPolicy: the rows that have not been erased, and whatever
// `scope` says of those.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func AddressPolicyNarrow(ctx context.Context, scope Scope, p predicate.AddressPolicy) (predicate.AddressPolicy, error) {
	ps := make([]predicate.AddressPolicy, 0, 3)

	// A row that was erased is not a row a read answers with.
	ps = append(ps, addresspolicy.DateErasedIsNil())
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.AddressPolicyScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return addresspolicy.And(ps...), nil
	}
}

// narrow is [AddressPolicyNarrow] with this server's own scope.
func (s AddressPolicyServiceServer) narrow(ctx context.Context, p predicate.AddressPolicy) (predicate.AddressPolicy, error) {
	return AddressPolicyNarrow(ctx, s.Scope, p)
}

