func (s AddressPolicyServiceServer) Erase(ctx context.Context, req *api.AddressPolicyRef) (*api.AddressPolicyEraseResponse, error) {
	p, err := AddressPolicyPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.AddressPolicy.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &api.AddressPolicyEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = addresspolicy.And(p, addresspolicy.IdEQ(v))
	}

	u := st.Db.AddressPolicy.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  api.AddressPolicyService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &api.AddressPolicyEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// AddressPolicyPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a AddressPolicy is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasAddressPolicyWith`, where no narrowing of a AddressPolicy
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func AddressPolicyPick(req *api.AddressPolicyRef) (predicate.AddressPolicy, error) {
	p, err := pickAddressPolicy(req)
	if err != nil {
		return nil, err
	}

	return addresspolicy.And(addresspolicy.DateErasedIsNil(), p), nil
}

func pickAddressPolicy(req *api.AddressPolicyRef) (predicate.AddressPolicy, error) {
	switch req.WhichKey() {
	case api.AddressPolicyRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return addresspolicy.IdEQ(v), nil
		}
	case api.AddressPolicyRef_Alias_case:
		return addresspolicy.AliasEQ(req.GetAlias()), nil
	case api.AddressPolicyRef_Version_case:
		return addresspolicy.VersionEQ(req.GetVersion()), nil
	case api.AddressPolicyRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: AddressPolicy")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
